TITLE = "มหานามสูตร (อนุสติ ๖)"
SUB = "อังคุตตรนิกาย ฉักกนิบาต (AN 6.10) · ระลึกถึงพระพุทธ พระธรรม พระสงฆ์ ศีล จาคะ เทวดา"
EXPAND = {}
TH = {
    "1": "สมัยหนึ่ง พระผู้มีพระภาคเจ้าประทับอยู่ที่นิโครธาราม ใกล้กรุงกบิลพัสดุ์ แคว้นสักกะ ครั้งนั้น เจ้ามหานามะศากยะเข้าไปเฝ้า กราบแล้วนั่งลง ณ ที่สมควร แล้วทูลถามว่า ข้าแต่พระองค์ผู้เจริญ อริยสาวกผู้บรรลุผล รู้แจ้งคำสอนแล้ว ย่อมอยู่ด้วยธรรมเครื่องอยู่อย่างไหนเป็นส่วนมาก",
    "2": "มหานามะ อริยสาวกผู้บรรลุผล รู้แจ้งคำสอนแล้ว ย่อมอยู่ด้วยธรรมเครื่องอยู่นี้เป็นส่วนมาก คือ อริยสาวกในธรรมวินัยนี้ ระลึกถึงพระตถาคตว่า “พระผู้มีพระภาคเจ้านั้น เป็นพระอรหันต์ ไกลจากกิเลส ตรัสรู้ชอบได้เอง ถึงพร้อมด้วยความรู้และความประพฤติ ไปดีแล้ว รู้แจ้งโลก เป็นผู้ฝึกคนที่ควรฝึกได้อย่างไม่มีใครยิ่งกว่า เป็นครูของเทวดาและมนุษย์ เป็นผู้รู้ ผู้ตื่น ผู้เบิกบาน เป็นผู้มีโชค ควรแก่การจำแนกธรรม” ในเวลาใด อริยสาวกระลึกถึงพระตถาคต ในเวลานั้น ใจของเธอไม่ถูกราคะครอบงำ ไม่ถูกโทสะครอบงำ ไม่ถูกโมหะครอบงำ ใจของเธอตรงแน่วต่อพระตถาคต ผู้มีใจตรงแน่ว ย่อมได้ความรู้แจ้งในอรรถ ได้ความรู้แจ้งในธรรม ได้ความปราโมทย์ที่ประกอบด้วยธรรม ผู้มีปราโมทย์ย่อมเกิดปีติ ผู้มีใจปีติกายย่อมสงบ ผู้มีกายสงบย่อมได้สุข ผู้มีสุขใจย่อมตั้งมั่น มหานามะ นี้เรียกว่า อริยสาวก ย่อมอยู่ร่วมกับหมู่สัตว์ที่ประพฤติไม่สม่ำเสมอได้อย่างสม่ำเสมอ อยู่กับหมู่สัตว์ที่พยาบาทได้อย่างไม่พยาบาท ถึงกระแสแห่งธรรมแล้ว เจริญพุทธานุสสติ",
    "3": "อีกข้อหนึ่ง อริยสาวกระลึกถึงพระธรรมว่า “พระธรรมที่พระผู้มีพระภาคเจ้าตรัสไว้ดีแล้ว เห็นได้ด้วยตัวเอง ไม่ขึ้นกับกาลเวลา ควรเรียกคนอื่นมาดูได้ ควรน้อมเข้ามาใส่ตัว คนมีปัญญารู้ได้เฉพาะตน” ในเวลาใด อริยสาวกระลึกถึงพระธรรม ในเวลานั้น ใจของเธอไม่ถูกราคะครอบงำ ไม่ถูกโทสะครอบงำ ไม่ถูกโมหะครอบงำ ใจของเธอตรงแน่วต่อพระธรรม ผู้มีใจตรงแน่ว ย่อมได้ความรู้แจ้งในอรรถ ได้ความรู้แจ้งในธรรม ได้ความปราโมทย์ที่ประกอบด้วยธรรม ผู้มีปราโมทย์ย่อมเกิดปีติ ผู้มีใจปีติกายย่อมสงบ ผู้มีกายสงบย่อมได้สุข ผู้มีสุขใจย่อมตั้งมั่น มหานามะ นี้เรียกว่า อริยสาวก ย่อมอยู่ร่วมกับหมู่สัตว์ที่ประพฤติไม่สม่ำเสมอได้อย่างสม่ำเสมอ อยู่กับหมู่สัตว์ที่พยาบาทได้อย่างไม่พยาบาท ถึงกระแสแห่งธรรมแล้ว เจริญธัมมานุสสติ",
    "4": "อีกข้อหนึ่ง อริยสาวกระลึกถึงพระสงฆ์ว่า “หมู่สาวกของพระผู้มีพระภาคเจ้า ปฏิบัติดี ปฏิบัติตรง ปฏิบัติเพื่อรู้ธรรม ปฏิบัติสมควร ได้แก่บุคคล ๔ คู่ นับเรียงตัวได้ ๘ ท่าน หมู่สาวกนี้ควรแก่ของที่เขานำมาบูชา ควรแก่การต้อนรับ ควรแก่ของทำบุญ ควรแก่การไหว้ เป็นนาบุญของโลกที่ไม่มีนาบุญใดยิ่งกว่า” ในเวลาใด อริยสาวกระลึกถึงพระสงฆ์ ในเวลานั้น ใจของเธอไม่ถูกราคะครอบงำ ไม่ถูกโทสะครอบงำ ไม่ถูกโมหะครอบงำ ใจของเธอตรงแน่วต่อพระสงฆ์ ผู้มีใจตรงแน่ว ย่อมได้ความรู้แจ้งในอรรถ ได้ความรู้แจ้งในธรรม ได้ความปราโมทย์ที่ประกอบด้วยธรรม ผู้มีปราโมทย์ย่อมเกิดปีติ ผู้มีใจปีติกายย่อมสงบ ผู้มีกายสงบย่อมได้สุข ผู้มีสุขใจย่อมตั้งมั่น มหานามะ นี้เรียกว่า อริยสาวก ย่อมอยู่ร่วมกับหมู่สัตว์ที่ประพฤติไม่สม่ำเสมอได้อย่างสม่ำเสมอ อยู่กับหมู่สัตว์ที่พยาบาทได้อย่างไม่พยาบาท ถึงกระแสแห่งธรรมแล้ว เจริญสังฆานุสสติ",
    "5": "อีกข้อหนึ่ง อริยสาวกระลึกถึงศีลของตนเอง ที่ไม่ขาด ไม่ทะลุ ไม่ด่าง ไม่พร้อย เป็นไท (ไม่เป็นทาสตัณหา) ผู้รู้สรรเสริญ ไม่ยึดติดผิด ๆ และช่วยให้ใจตั้งมั่น ในเวลาใด อริยสาวกระลึกถึงศีล ในเวลานั้น ใจของเธอไม่ถูกราคะครอบงำ ไม่ถูกโทสะครอบงำ ไม่ถูกโมหะครอบงำ ใจของเธอตรงแน่วต่อศีล ผู้มีใจตรงแน่ว ย่อมได้ความรู้แจ้งในอรรถ ได้ความรู้แจ้งในธรรม ได้ความปราโมทย์ที่ประกอบด้วยธรรม ผู้มีปราโมทย์ย่อมเกิดปีติ ผู้มีใจปีติกายย่อมสงบ ผู้มีกายสงบย่อมได้สุข ผู้มีสุขใจย่อมตั้งมั่น มหานามะ นี้เรียกว่า อริยสาวก ย่อมอยู่ร่วมกับหมู่สัตว์ที่ประพฤติไม่สม่ำเสมอได้อย่างสม่ำเสมอ อยู่กับหมู่สัตว์ที่พยาบาทได้อย่างไม่พยาบาท ถึงกระแสแห่งธรรมแล้ว เจริญสีลานุสสติ",
    "6": "อีกข้อหนึ่ง อริยสาวกระลึกถึงการให้ของตนว่า “เป็นลาภของเราแล้วหนอ เราได้ดีแล้วหนอ ที่เราอยู่ครองเรือน ท่ามกลางหมู่ชนที่ถูกมลทินคือความตระหนี่ครอบงำ แต่มีใจปราศจากมลทินคือความตระหนี่ เป็นผู้บริจาคเสมอ มือพร้อมจะให้ ยินดีในการสละ พร้อมให้แก่ผู้ขอ ยินดีในการแบ่งปันทาน” ในเวลาใด อริยสาวกระลึกถึงการให้ ในเวลานั้น ใจของเธอไม่ถูกราคะครอบงำ ไม่ถูกโทสะครอบงำ ไม่ถูกโมหะครอบงำ ใจของเธอตรงแน่วต่อการให้ ผู้มีใจตรงแน่ว ย่อมได้ความรู้แจ้งในอรรถ ได้ความรู้แจ้งในธรรม ได้ความปราโมทย์ที่ประกอบด้วยธรรม ผู้มีปราโมทย์ย่อมเกิดปีติ ผู้มีใจปีติกายย่อมสงบ ผู้มีกายสงบย่อมได้สุข ผู้มีสุขใจย่อมตั้งมั่น มหานามะ นี้เรียกว่า อริยสาวก ย่อมอยู่ร่วมกับหมู่สัตว์ที่ประพฤติไม่สม่ำเสมอได้อย่างสม่ำเสมอ อยู่กับหมู่สัตว์ที่พยาบาทได้อย่างไม่พยาบาท ถึงกระแสแห่งธรรมแล้ว เจริญจาคานุสสติ",
    "7": "อีกข้อหนึ่ง อริยสาวกเจริญเทวตานุสสติว่า “เทวดาชั้นจาตุมหาราชิกามีอยู่ ชั้นดาวดึงส์มีอยู่ ชั้นยามามีอยู่ ชั้นดุสิตมีอยู่ ชั้นนิมมานรดีมีอยู่ ชั้นปรนิมมิตวสวัตดีมีอยู่ ชั้นพรหมกายิกามีอยู่ ชั้นที่สูงกว่านั้นก็มีอยู่ เทวดาเหล่านั้นมีศรัทธา ศีล สุตะ จาคะ ปัญญาแบบใด จึงจุติจากโลกนี้ไปเกิดที่นั่น เราก็มีแบบนั้น” ในเวลาใด อริยสาวกระลึกถึงศรัทธา ศีล สุตะ จาคะ ปัญญา ทั้งของตนและของเทวดาเหล่านั้น ในเวลานั้น ใจของเธอไม่ถูกราคะ โทสะ โมหะครอบงำ ใจตรงแน่วต่อเทวดาเหล่านั้น ผู้มีใจตรงแน่ว ย่อมได้ความรู้แจ้งในอรรถ ในธรรม ได้ความปราโมทย์ที่ประกอบด้วยธรรม ผู้มีปราโมทย์ย่อมเกิดปีติ ผู้มีใจปีติกายย่อมสงบ ผู้มีกายสงบย่อมได้สุข ผู้มีสุขใจย่อมตั้งมั่น มหานามะ นี้เรียกว่า อริยสาวก ย่อมอยู่ร่วมกับหมู่สัตว์ที่ประพฤติไม่สม่ำเสมอได้อย่างสม่ำเสมอ อยู่กับหมู่สัตว์ที่พยาบาทได้อย่างไม่พยาบาท ถึงกระแสแห่งธรรมแล้ว เจริญเทวตานุสสติ",
    "8": "มหานามะ อริยสาวกผู้บรรลุผล รู้แจ้งคำสอนแล้ว ย่อมอยู่ด้วยธรรมเครื่องอยู่นี้เป็นส่วนมาก (จบสูตรที่ ๑๐)",
    "9": "หัวข้อประจำวรรค: สองสูตรว่าด้วยผู้ควรแก่ของบูชา อินทรีย์ ๕ พละ ๓ อาชานียะ ๓ อนุตตริยะ ๖ อนุสติ ๖ ทั้ง ๑๐ สูตรนี้ทรงแสดงแก่เจ้ามหานามะ",
}
